#include "check.h"
#include "animation/animation_targets.h"
using namespace matter;using namespace matter::animation;
namespace { SourceSpan src(){return {"ik",1,1,""};} AnimationTransform at(float x){AnimationTransform t;t.translation.x=x;return t;} void test_chain(){RigDefinition rig;rig.joints={{"root","",at(0),1,src()},{"a","root",at(1),1,src()},{"b","a",at(1),1,src()},{"end","b",at(1),1,src()},{"child","end",at(1),1,src()}};Diagnostics d;OzzSkeleton s;CHECK(build_skeleton(rig,s,d),"builds ik chain");JointIndex mid;JointRange range;CHECK(resolve_two_bone_chain(s,1,3,mid,range)&&mid==2,"infers inclusive start/end chain");CHECK(!resolve_two_bone_chain(s,0,3,mid,range),"v1 rejects non-two-segment chain");CanonicalTarget t{};t.chain={1,2,3};t.has_pole=true;t.pole={0,1,0};AnimationTargetState st{};st.evaluated.translation={2,1,0};std::vector<AnimationTransform> locals;for(auto&j:rig.joints)locals.push_back(j.local);std::vector<Mat4f> models;CHECK(local_to_model(s,locals,models),"initial model conversion");CHECK(solve_animation_target(t,s,st,locals,models),"two bone solve updates pose");CHECK(models.size()==locals.size(),"solver returns fresh descendant model matrices");CanonicalTarget other{};other.chain={3,4,4};CHECK(!validate_exclusive_target_chains({t,other}),"overlapping writable chains reject");} }
int main(){test_chain();return check_summary();}
